Translate("zhCN", "humans", {
	title = "人类",
	sections = {
		{
			title = "概述",
			text = [=[人类是{link:eastern-kingdoms}东部王国{/link}年轻种族中人数最多的。与精灵和{link:dwarves}矮人{/link}相比，他们的寿命短暂，但他们不安分、坚韧且学得很快。从他们的血脉中崛起了北方和南方的伟大王国，从他们的行列中走出了{link:holy-light}圣光{/link}的圣骑士和{link:dalaran}达拉然{/link}的法师。在对抗{link:orcs}兽人{/link}和亡灵的战争中，他们比任何其他种族承受了更多的苦难，而他们至今尚未崩溃。]=],
		},
		{
			title = "起源",
			text = [=[在远古时代，人类是分散在北方的{link:horde}部落{/link}，彼此互不信任。唯有{link:arathi-highlands}阿拉希{/link}部落看出，阿曼尼{link:trolls}巨魔{/link}帝国会将他们逐个消灭。他们的军事领袖{link:thoradin}索拉丁{/link}以力量和劝说将各部落团结在一起，并在联合的基础上建立了{link:arathor}阿拉索{/link}王国及其要塞城市斯特罗姆。当阿曼尼进攻{link:quel-thalas}奎尔萨拉斯{/link}的{link:high-elves}高等精灵{/link}时，阿拉索响应了精灵的呼唤。精灵们将{link:arcane-magic}奥术魔法{/link}传授给一百名人类，两个种族一起在{link:troll-wars}巨魔战争{/link}中击溃了阿曼尼。

在随后的漫长和平中，阿拉索的团结逐渐消退。它的人民散布到各地，建立了新的国度：北方的{link:lordaeron}洛丹伦{/link}，{link:western-strand}西部海岸{/link}的{link:gilneas}吉尔尼斯{/link}和{link:kul-tiras}库尔提拉斯{/link}，山中的{link:alterac-mountains}奥特兰克{/link}和{link:stromgarde-keep}激流堡{/link}，位于{link:dalaran}达拉然{/link}的{link:city-of-dalaran}法师之城{/link}，以及遥远南方的{link:azeroth}艾泽拉斯{/link}王国，如今人们称之为{link:kingdom-of-stormwind}暴风王国{/link}。]=],
		},
		{
			title = "天性与习俗",
			text = [=[人类是一个由国王和农夫组成的民族。他们的贵族守着古老的家族和更古老的宿怨，而他们的平民耕种土地，对两者都不甚在意。{link:holy-light}圣光{/link}教会将他们中的许多人联系在一起，每个村庄都有它的牧师。人类重视誓言、勇气和职责，尽管他们并不总能信守。他们最大的天赋是重建。无论什么被焚毁，他们都会再次建起来。]=],
		},
		{
			title = "当今",
			text = [=[人类诸王国已是昔日荣光的影子。{link:scourge}天灾军团{/link}占据着{link:lordaeron}洛丹伦{/link}的废墟，{link:scarlet-crusade}血色十字军{/link}在北方进行着自己的无情战争。{link:gilneas}吉尔尼斯{/link}把自己关在它的巨墙之后。{link:alterac-mountains}奥特兰克{/link}已成废墟，{link:stromgarde-keep}激流堡{/link}紧守着{link:arathi-highlands}阿拉希高地{/link}残存的土地。在南方，{link:stormwind-city}暴风城{/link}已经重建，但国王{link:varian-wrynn}瓦里安·乌瑞恩{/link}失踪了，大领主{link:bolvar-fordragon}伯瓦尔·弗塔根{/link}以他的名义统治。在大海对岸，{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}女士守护着岛上要塞{link:theramore-isle}塞拉摩{/link}，人类在那里与{link:horde}部落{/link}维持着一种不安的和平。人类仍是{link:alliance}联盟{/link}的心脏，而这颗心正在流血。]=],
		},
	},
})

Translate("zhCN", "dwarves", {
	title = "矮人",
	aliases = { "矮人" },
	sections = {
		{
			title = "概述",
			text = [=[矮人是卡兹莫丹群山中一个结实而坚韧的民族。他们是矿工、铁匠、酿酒师和战士，也是世上最出色的工匠之一。他们的伟大城市{link:ironforge}铁炉堡{/link}开凿在一座山的心脏之中。自{link:second-war}第二次战争{/link}以来，他们一直与{link:humans}人类{/link}并肩作战，至今仍是{link:alliance}联盟{/link}的支柱之一。]=],
		},
		{
			title = "起源",
			text = [=[漫长岁月里，矮人生活在群山之下，他们自己的传说称他们是由石头塑造而成的。在{link:uldaman}奥达曼{/link}的殿堂中，{link:explorers-league}探险者协会{/link}的学者发现了泰坦的记录，这些记录似乎证实了这一点：它们提到了土灵，这是泰坦创造的活岩石生物，用来塑造世界的深处。许多矮人如今相信，他们的种族是土灵的后裔。

矮人长久以来统一在{link:ironforge}铁炉堡{/link}的一位至高王之下。那位国王死后，三大氏族为争夺他的王位而开战。在这场三锤之战中，铜须氏族守住了铁炉堡。蛮锤氏族被赶到北方，最终在{link:the-hinterlands}辛特兰{/link}安了家。{link:dark-iron-dwarves}黑铁氏族{/link}被逐往南方。在那里，他们的巫师之王{link:ruins-of-thaurissan}索瑞森{/link}寻求一种力量来报复他的失败，他召唤出了炎魔之王{red:ragnaros}拉格纳罗斯{/red}。那次召唤的烈火撕裂了大地，并将黑铁矮人束缚为炎魔之王的仆从。]=],
		},
		{
			title = "天性与习俗",
			text = [=[矮人骄傲、忠诚，而且不轻易原谅。他们喜爱好麦酒、响亮的歌声和一把做工精良的斧头。他们看重行动胜过言语，以记性长久而闻名。他们的枪匠闻名整个{link:eastern-kingdoms}东部王国{/link}，他们的步枪和火炮守住过许多城墙。蛮锤矮人比他们的同族更狂野，骑着狮鹫投入战斗，而铜须矮人更偏爱{link:the-cauldron}熔炉{/link}和步枪。]=],
		},
		{
			title = "当今",
			text = [=[国王{link:magni-bronzebeard}麦格尼·铜须{/link}统治着{link:ironforge}铁炉堡{/link}。他的兄弟{link:brann-bronzebeard}布莱恩·铜须{/link}领导着{link:explorers-league}探险者协会{/link}，协会的发掘者们在世界各地的废墟中挖掘，寻找矮人真正的过去。铁炉堡向失去了城市的{link:gnomes}侏儒{/link}敞开了大门，那座城市落入了{link:troggs}石腭怪{/link}之手，如今{link:tinker-town}侏儒区{/link}回荡着侏儒们工作的声音。{link:dark-iron-dwarves}黑铁矮人{/link}仍是他们同族最痛恨的敌人，他们在{link:blackrock-mountain}黑石山{/link}深处为炎魔之王劳作。蛮锤矮人在{link:the-hinterlands}辛特兰{/link}自行其是，是铁炉堡的盟友，却从不是它的臣民。]=],
		},
	},
})

Translate("zhCN", "gnomes", {
	title = "侏儒",
	aliases = { "侏儒" },
	sections = {
		{
			title = "概述",
			text = [=[侏儒是一个身材矮小、聪明机灵、好奇心永无止境的民族。他们是世上最伟大的工匠和工程师，在遇到的每一样东西里都能看到一个有待解决的问题。世世代代，他们住在{link:dun-morogh}丹莫罗{/link}群山中那座奇妙的城市{link:gnomeregan}诺莫瑞根{/link}。如今那座城市已经失落，他们作为{link:dwarves}矮人{/link}的客人住在{link:ironforge}铁炉堡{/link}。]=],
		},
		{
			title = "起源",
			text = [=[侏儒长久以来是卡兹莫丹{link:dwarves}矮人{/link}的邻居和朋友。关于他们最早的时代，{link:azeroth}艾泽拉斯{/link}的史书记载甚少。可以确定的是，他们亲手建造了{link:gnomeregan}诺莫瑞根{/link}，并在其中装满了奇迹：巨大的引擎、发条仆从，以及任何其他民族都无法想象的装置。在{link:second-war}第二次战争{/link}中，他们与矮人一起加入了{link:alliance}联盟{/link}。他们派出的士兵不多，因为他们并非人口众多的民族，但他们为联盟提供了飞行器、潜水艇和他们自己设计的武器。]=],
		},
		{
			title = "天性与习俗",
			text = [=[侏儒即便在最黑暗的时刻也聪颖、敏捷而乐观。他们也很容易分心，他们的发明并不总是按照制造者的意图运作。他们看重聪明胜过力量，并给予他们的工程大师最高的荣誉。他们的领袖拥有大工匠的头衔。许多侏儒也研习{link:arcane-magic}奥术魔法{/link}，有些人则转向了别人认为最好不要触碰的黑暗技艺。]=],
		},
		{
			title = "当今",
			text = [=[{link:third-war}第三次战争{/link}之后，{link:troggs}石腭怪{/link}从地下涌出，涌入了{link:gnomeregan}诺莫瑞根{/link}。这座城市守不住了。大工匠{link:gelbin-mekkatorque}格尔宾·梅卡托克{/link}做出了一个孤注一掷的选择，释放了一种毒性武器来驱逐入侵者。它杀死了许多石腭怪，但也杀死了大量的侏儒，并使城市遭到了污染。幸存者逃往{link:ironforge}铁炉堡{/link}。如今有传言说，这次陷落并非意外：据说大工匠自己的顾问{link:mekgineer-thermaplugg}希科·瑟玛普拉格{/link}背叛了他的人民，如今作为那座废城的疯狂主人统治着它。侏儒们梦想着夺回家园的那一天。在那之前，他们在铁炉堡钻研发明，并以一如既往的热忱为{link:alliance}联盟{/link}效力。]=],
		},
	},
})

Translate("zhCN", "night-elves", {
	title = "暗夜精灵",
	aliases = { "卡多雷", "暗夜精灵" },
	sections = {
		{
			title = "概述",
			text = [=[暗夜精灵自称卡多雷，意为“星辰之子”，是{link:kalimdor}卡利姆多{/link}最古老的文明种族。他们身材高大，皮肤紫罗兰色，寿命悠长，一万年来一直守护着北方的森林。他们的女祭司侍奉月神艾露恩，他们的德鲁伊按照半神{link:cenarius}塞纳留斯{/link}所传授的方式照料着荒野。{link:third-war}第三次战争{/link}之后，他们在历史上第一次加入了{link:alliance}联盟{/link}。]=],
		},
		{
			title = "起源",
			text = [=[最早的暗夜精灵是远古时代定居在{link:well-of-eternity}永恒之井{/link}岸边的一个{link:horde}部落{/link}。永恒之井的力量改变了他们，赐予他们悠长的寿命。他们在井岸上建立了一个伟大的帝国，由{link:queen-azshara}艾萨拉女王{/link}和她的上层精灵术士阶层统治。上层精灵沉醉于永恒之井的力量，最终他们的魔法引起了{link:burning-legion}燃烧军团{/link}的注意。{link:azshara}艾萨拉{/link}为恶魔打开了通道，{link:war-of-the-ancients}上古战争{/link}由此爆发。

德鲁伊{link:malfurion-stormrage}玛法里奥·怒风{/link}、女祭司{link:tyrande-whisperwind}泰兰德·语风{/link}和他们的盟友击退了燃烧军团。最终永恒之井被摧毁，{link:great-sundering}大分裂{/link}粉碎了古老的大陆。幸存的暗夜精灵摒弃了{link:arcane-magic}奥术魔法{/link}。他们在{link:mount-hyjal}海加尔山{/link}上培育了一棵新的生命之树{link:nordrassil}诺达希尔{/link}，它赐予了他们永生。拒绝放弃魔法的上层精灵被流放到大海彼岸。]=],
		},
		{
			title = "天性与习俗",
			text = [=[暗夜精灵是一个耐心而警觉的民族。他们的女性长久以来担任{link:sentinels}哨兵{/link}，即守护森林的战士，而他们的男性则成为德鲁伊，在{link:emerald-dream}翡翠梦境{/link}中沉睡多年。他们热爱世界上的荒野之地，憎恨那些破坏荒野的人。他们不信任奥术，因为它几乎终结了他们的世界。]=],
		},
		{
			title = "当今",
			text = [=[在{link:third-war}第三次战争{/link}中，{link:burning-legion}燃烧军团{/link}卷土重来。在{link:battle-of-mount-hyjal}海加尔山之战{/link}中，暗夜精灵、{link:humans}人类{/link}和{link:orcs}兽人{/link}共同对抗{link:archimonde}阿克蒙德{/link}，{link:nordrassil}诺达希尔{/link}的力量被耗尽以消灭他。暗夜精灵也随之失去了永生。大德鲁伊{link:fandral-staghelm}范达尔·鹿盔{/link}和他的德鲁伊们随后在北方海岸外种下了一棵新的世界之树{link:teldrassil}泰达希尔{/link}，{link:darnassus}达纳苏斯{/link}城在它的枝干间成长起来。{link:tyrande-whisperwind}泰兰德{/link}作为高阶女祭司在那里统治，而{link:malfurion-stormrage}玛法里奥{/link}行走于{link:emerald-dream}翡翠梦境{/link}之中，至今未归。卡多雷如今面对着砍伐{link:ashenvale}灰谷{/link}森林的兽人，以及在{link:felwood}费伍德森林{/link}中蔓延的腐化。]=],
		},
	},
})

Translate("zhCN", "orcs", {
	title = "兽人",
	aliases = { "兽人" },
	sections = {
		{
			title = "概述",
			text = [=[兽人是来自德拉诺世界的一个骄傲的战士民族。他们作为征服者穿过{link:dark-portal}黑暗之门{/link}来到{link:azeroth}艾泽拉斯{/link}，给{link:humans}人类{/link}诸王国带来了烈火与毁灭。他们被击败、被囚禁、被摧垮，却再次崛起。在大酋长{link:thrall}萨尔{/link}的领导下，他们渡海来到{link:kalimdor}卡利姆多{/link}，在{link:durotar}杜隆塔尔{/link}建立了新的家园。他们是{link:horde}部落{/link}的核心。]=],
		},
		{
			title = "起源",
			text = [=[在德拉诺，兽人分为许多氏族。他们是猎人和战士，由与{link:elements}元素{/link}之灵交谈的萨满祭司引导。恶魔领主{link:kil-jaeden}基尔加丹{/link}决意把他们变成{link:burning-legion}燃烧军团{/link}的武器。他欺骗了年长的萨满祭司{link:ner-zhul}耐奥祖{/link}，后来又欺骗了耐奥祖的学徒{link:gul-dan}古尔丹{/link}。古尔丹向各氏族传授术士的技艺，元素因此背弃了兽人。最终，酋长们喝下了恶魔{link:mannoroth}玛诺洛斯{/link}的血，嗜血的狂怒攫住了整个民族。

{link:horde}部落{/link}穿过{link:dark-portal}黑暗之门{/link}，扑向{link:azeroth}艾泽拉斯{/link}王国。它赢得了{link:first-war}第一次战争{/link}，焚毁了{link:stormwind-city}暴风城{/link}。在{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}的率领下，它几乎也赢得了{link:second-war}第二次战争{/link}，却因内部的背叛而战败。幸存的兽人被赶进了{link:internment-camps}收容所{/link}，一种奇怪的倦怠笼罩了他们。]=],
		},
		{
			title = "天性与习俗",
			text = [=[兽人崇尚力量、勇气和对氏族的忠诚。他们尊敬为灵魂代言的萨满祭司，也尊敬在战斗中坚定不移的战士。他们的名字是骄傲的，他们的记忆也是如此：每个氏族都保留着自己的传说和自己的宿怨。自从恶魔的诅咒终结以来，许多兽人回归了萨满的古老道路，寻求与{link:elements}元素{/link}的平衡。]=],
		},
		{
			title = "当今",
			text = [=[年轻的兽人{link:thrall}萨尔{/link}在一座{link:humans}人类{/link}要塞中作为奴隶长大，他逃离了主人，并把他的族人从{link:internment-camps}收容所{/link}中解放出来。应一位先知的召唤，他率领他们西行前往{link:kalimdor}卡利姆多{/link}。在那里，在{link:third-war}第三次战争{/link}中，{link:grom-hellscream}格罗姆·地狱咆哮{/link}杀死了{link:mannoroth}玛诺洛斯{/link}，将兽人从恶魔之血中解放出来。萨尔以他父亲杜隆坦的名字将他的新土地命名为{link:durotar}杜隆塔尔{/link}，又以毁灭之锤的名字将他的首都命名为{link:orgrimmar}奥格瑞玛{/link}。兽人如今与{link:theramore-isle}塞拉摩{/link}维持着一种不安的和平。然而，并非所有兽人都已背弃古老的黑暗。{link:burning-blade}火刃氏族{/link}的邪教在杜隆塔尔的洞穴中低语，而在{link:eastern-kingdoms}东部王国{/link}，{link:blackrock-clan}黑石氏族{/link}仍在{link:blackrock-mountain}黑石山{/link}中侍奉黑龙。]=],
		},
	},
})

Translate("zhCN", "trolls", {
	title = "巨魔",
	sections = {
		{
			title = "概述",
			text = [=[巨魔是{link:azeroth}艾泽拉斯{/link}最古老的种族之一。他们身材高大，长着獠牙，性情凶猛，他们的身体能治愈足以杀死任何其他生物的伤口。早在{link:night-elves}暗夜精灵{/link}建立帝国之前，巨魔就统治着他们自己的伟大国度。那些帝国已经陨落，残存的部族心怀怨恨、四分五裂且危险。其中之一，{link:darkspear-trolls}暗矛巨魔{/link}部族，如今与{link:horde}部落{/link}站在一起。]=],
		},
		{
			title = "起源",
			text = [=[最古老的巨魔王国属于赞达拉，他们的部族居住在遥远的南方。远古时代的两大帝国皆源于他们：北方森林中的阿曼尼和南方丛林中的古拉巴什。他们崇拜被称为洛阿的强大灵魂，曾与早期的{link:night-elves}暗夜精灵{/link}交战并落败。{link:great-sundering}大分裂{/link}撕裂了他们的土地。

阿曼尼从未原谅定居在他们森林中的{link:high-elves}高等精灵{/link}。在{link:troll-wars}巨魔战争{/link}中，他们几乎摧毁了{link:quel-thalas}奎尔萨拉斯{/link}，直到{link:arathor}阿拉索{/link}的{link:humans}人类{/link}与精灵联手击溃了他们。在南方，当阿塔莱的祭司召唤出血神{link:hakkar}哈卡{/link}时，古拉巴什陷入了内战。各部族推翻了这位神，并把阿塔莱赶进了{link:swamp-of-sorrows}沼泽{/link}，他们在那里建造了{link:temple-of-atal-hakkar}阿塔哈卡神庙{/link}。他们的帝国再也没有恢复过来。]=],
		},
		{
			title = "天性与习俗",
			text = [=[巨魔是猎人和劫掠者。他们的祭司施行巫毒，与洛阿交谈，他们的巫医调制让其他种族畏惧的药剂和咒术。许多部族坚守着残忍的习俗，据说有些部族会吃掉他们的敌人。他们以自己古老的过去为傲，并怨恨那些夺走他们土地的年轻种族。很少有巨魔信任外人，而得到外人信任的巨魔更少。]=],
		},
		{
			title = "当今",
			text = [=[{link:darkspear-trolls}暗矛部族{/link}被逐出了丛林中的家园，在南方的海域找到了避难所。在那里，{link:thrall}萨尔{/link}把他们从{link:humans}人类{/link}和海巫手中救了出来，他们的首领森{link:ginro-hearthkindle}金{/link}献出了自己的生命，好让他的族人能够追随{link:orcs}兽人{/link}。如今暗矛巨魔在{link:vol-jin}沃金{/link}的领导下为{link:horde}部落{/link}效力。他们定居在{link:durotar}杜隆塔尔{/link}外海的{link:echo-isles}回音群岛{/link}，但一个名叫{link:zalazane}扎拉赞恩{/link}的巫医用黑暗魔法夺取了这些岛屿，部族已退守到大陆上的{link:sen-jin-village}森金村{/link}。在其他地方，巨魔部族仍是所有人的敌人：北方森林中的阿曼尼，{link:the-hinterlands}辛特兰{/link}的{link:witherbark-trolls}枯木{/link}和邪枝，{link:stranglethorn-vale}荆棘谷{/link}的古拉巴什诸部族，{link:tanaris}塔纳利斯{/link}的{link:sandfury-trolls}沙怒{/link}，以及{link:dun-morogh}丹莫罗{/link}的{link:frostmane-trolls}霜鬃{/link}。]=],
		},
	},
})

Translate("zhCN", "tauren", {
	title = "牛头人",
	aliases = { "牛头人", "舒哈鲁" },
	sections = {
		{
			title = "概述",
			text = [=[牛头人是一个身材高大、智慧温和的民族，漫游在{link:kalimdor}卡利姆多{/link}的{link:burning-steppes}平原{/link}上。他们体型巨大，形似公牛，在战斗中可以十分可怕，但他们更愿意与大地和平共处。他们崇敬大地母亲胜过一切。在他们伟大的酋长{link:cairne-bloodhoof}凯恩·血蹄{/link}的领导下，他们定居在{link:mulgore}莫高雷{/link}的草原上，并加入了{link:horde}部落{/link}。]=],
		},
		{
			title = "起源",
			text = [=[牛头人自称舒哈鲁，是{link:kalimdor}卡利姆多{/link}最古老的种族之一。漫长岁月里，他们作为游牧民在{link:burning-steppes}平原{/link}上漫游，追随着大兽群和季节的轮转。他们说，大地母亲赐予了他们这片土地，太阳和月亮是她的双眼，他们称之为安舍和穆莎。各{link:horde}部落{/link}分开生活，各有自己的酋长和图腾。

这样的生活几乎被{link:centaurs}半人马{/link}终结。平原上残忍的马人世世代代猎杀分散的部落，把他们赶出了祖先的土地。{link:cairne-bloodhoof}凯恩·血蹄{/link}立志要团结各部落对抗他们。{link:orcs}兽人{/link}来到卡利姆多时，凯恩遇见了年轻的{link:thrall}萨尔{/link}，两个民族认出彼此是精神上的亲族。在兽人的帮助下，牛头人打破了半人马对{link:mulgore}莫高雷{/link}的控制，并将其作为自己的家园。]=],
		},
		{
			title = "天性与习俗",
			text = [=[牛头人与大地亲近地生活。他们怀着敬意狩猎，只取所需。他们的萨满祭司与{link:elements}元素{/link}之灵和祖先之灵交谈，一些牛头人在{link:cenarion-circle}塞纳里奥议会{/link}的{link:night-elves}暗夜精灵{/link}的训练下学会了德鲁伊之道。他们耐心、不易动怒，而且诚实得过了头。他们的图腾记录着各{link:horde}部落{/link}的世系和事迹。]=],
		},
		{
			title = "当今",
			text = [=[牛头人在{link:mulgore}莫高雷{/link}上方的高台上建起了他们的首都{link:thunder-bluff}雷霆崖{/link}，要通过巨大的{link:the-great-lift}升降梯{/link}才能抵达。{link:cairne-bloodhoof}凯恩{/link}作为大酋长在那里统治，就连畏惧{link:horde}部落{/link}的人也尊敬他。并非所有部落都认同他的愿景。由年老的女巫{link:magatha-grimtotem}玛加萨{/link}领导的{link:grimtotem-clan}恐怖图腾{/link}部落怀有自己的野心，雷霆崖中许多人都不太信任它。在莫高雷周围，牛头人仍面对着敌人：刺背部落的{link:quilboar}野猪人{/link}、山脊上的{link:harpies}鹰身人{/link}，以及{link:the-barrens}贫瘠之地{/link}的{link:centaurs}半人马{/link}。牛头人铭记他们欠{link:orcs}兽人{/link}的恩情，他们是部落中最坚定的成员之一。]=],
		},
	},
})

Translate("zhCN", "forsaken", {
	title = "被遗忘者",
	sections = {
		{
			title = "概述",
			text = [=[被遗忘者是挣脱了巫妖王意志的亡灵。他们曾经是{link:lordaeron}洛丹伦{/link}的人民。他们死于瘟疫，作为{link:scourge}天灾军团{/link}的奴隶复活，然后，在他们主人的控制出现片刻松动之时，重新找回了自己的心智。他们追随女妖之王{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}，在他们旧都的废墟之下建立了一个黑暗王国。出于他们自己的理由，他们加入了{link:horde}部落{/link}。]=],
		},
		{
			title = "起源",
			text = [=[在{link:third-war}第三次战争{/link}中，{link:cult-of-the-damned}诅咒教派{/link}的瘟疫席卷了{link:lordaeron}洛丹伦{/link}，王子{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}谋杀了他的父亲{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}，并把王国交给了{link:scourge}天灾军团{/link}。成千上万的死者复活，为巫妖王效力。有一段时间，他们完全没有自己的意志。

后来巫妖王的力量减弱了，洛丹伦的许多亡灵发现自己又能独立思考了。{link:quel-thalas}奎尔萨拉斯{/link}陨落的游侠将军{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}曾被阿尔萨斯亲手复活为女妖。她与他们一同挣脱了束缚。她反抗那些企图统治这个毁灭王国的恐惧魔王，并将其中之一{link:varimathras}瓦里玛萨斯{/link}束缚为自己的仆从。她把她的人民命名为被遗忘者，并率领他们将洛丹伦旧都的废墟据为己有。]=],
		},
		{
			title = "天性与习俗",
			text = [=[被遗忘者记得他们生前的一切，却无法回到过去。他们的朋友和亲人畏惧并憎恨他们，他们中的许多人也学会了以憎恨回报。他们冷峻、怨恨而务实。他们的学者毫无顾忌地钻研炼{link:ginro-hearthkindle}金{/link}术和死灵术的一切技艺，他们的牧师已从{link:holy-light}圣光{/link}转向了暗影。在生者之中，他们被容忍，而非被信任。]=],
		},
		{
			title = "当今",
			text = [=[在{link:lordaeron}洛丹伦{/link}破碎的城市之下，被遗忘者建起了{link:undercity}幽暗城{/link}，一座建在古老王室墓穴中的厅堂与下水道构成的迷宫。{link:sylvanas-windrunner}希尔瓦娜斯{/link}从那里统治着{link:tirisfal-glades}提瑞斯法林地{/link}，并在两条战线上作战：对抗仍占据着瘟疫之地的{link:scourge}天灾军团{/link}，以及对抗见到亡灵就烧的{link:scarlet-crusade}血色十字军{/link}。他们与{link:horde}部落{/link}的同盟是出于需要。{link:orcs}兽人{/link}和{link:tauren}牛头人{/link}觉得他们古怪而令人不安。而被遗忘者对自己的真正目的则很少提及，{link:royal-apothecary-society}皇家药剂师协会{/link}的药剂师们正在秘密研制一种新的瘟疫。]=],
		},
	},
})

Translate("zhCN", "skyborne", {
	title = "天裔",
	aliases = { "申多雷" },
	sections = {
		{
			title = "概述",
			text = [=[天裔自称申多雷，意为“隐秘之民”，是在世界之外生活了数千年的精灵。他们的家园是{link:zephras-isle}泽弗拉斯岛{/link}，一座漂浮在气{link:elements}元素{/link}位面{link:skywall}天空之墙{/link}中的岛屿。他们与上层精灵同出一脉，是{link:quel-thalas}奎尔萨拉斯{/link}的{link:high-elves}高等精灵{/link}的表亲。如今他们的天空国度正在衰败，新一代的天裔已降临{link:azeroth}艾泽拉斯{/link}，寻找答案。]=],
		},
		{
			title = "起源",
			text = [=[天裔将他们的血统追溯到埃尔德{link:farmer-ray}雷{/link}萨拉斯的上层精灵，那座位于{link:feralas}菲拉斯{/link}的城市如今被称为{red:dire-maul}厄运之槌{/red}。{link:war-of-the-ancients}上古战争{/link}之后，王子{red:tortheldrin}托塞德林{/red}试图用越来越危险的力量维持这座城市。他的一些子民见识过这种对力量的渴求给世界带来了什么，于是起来反抗他。他们挫败了他的图谋，但他们的叛乱被镇压，他们渡海而逃，王子的舰队紧追其后。

在遥远的西方，他们来到一片由古老的{link:elements}元素{/link}之灵统治的土地。他们在那里与{link:vanishing-of-the-wind-spirits}风之灵{/link}订立了契约。风之灵将那片土地的一大块撕扯到天空中，带离了这个世界，并把它锚定在{link:skywall}天空之墙{/link}。流亡者们躲开了追兵，在云层之间建立了一个小而辉煌的文明。]=],
		},
		{
			title = "天性与习俗",
			text = [=[在{link:skywall}天空之墙{/link}的漫长岁月改变了申多雷。他们变得比祖先更轻盈、更敏捷，空气的魔法在他们的头发、眼睛和皮肤上留下了印记。他们作为学生和朋友与{link:vanishing-of-the-wind-spirits}风之灵{/link}比邻而居。他们中有些人获得了风之灵赐予的天视之力，能够看穿整个{link:elements}元素{/link}位面。风之灵很少提起风王{link:al-akir}奥拉基尔{/link}，天空之墙的主宰，在天裔之中，他的名字成了令人恐惧、讳莫如深的东西。]=],
		},
		{
			title = "当今",
			text = [=[毫无预兆地，{link:vanishing-of-the-wind-spirits}风之灵{/link}消失了。维系{link:zephras-isle}泽弗拉斯岛{/link}的古老塔柱开始失效，岛屿的部分地区已沦为废墟，各个聚落彼此隔绝。天裔对于该怎么做意见分歧。

• {b}{link:windshapers}塑风者{/link}。{/b}他们是最早获得天视之力的申多雷的后裔，是岛上的精神向导。他们寻求了解风之灵的下落并让它们回归。他们加入了{link:horde}部落{/link}。
• {b}高等教团。{/b}他们是逃离埃尔德{link:farmer-ray}雷{/link}萨拉斯的上层精灵魔导师的后裔，认为天裔过于信任他们的庇护者。他们寻找祖先失落的奥术知识，好让他们的人民能够自立。他们加入了{link:alliance}联盟{/link}。
• {b}{link:al-aketh}奥拉凯斯{/link}。{/b}一个背弃了其他申多雷、转而侍奉{link:al-akir}奥拉基尔{/link}的教派。风之灵的缺席让他们胆大妄为，他们散布恐惧，占领了岛上的大片地区。]=],
		},
	},
})

Translate("zhCN", "high-elves", {
	title = "高等精灵",
	aliases = { "奎尔多雷", "高等精灵" },
	sections = {
		{
			title = "概述",
			text = [=[高等精灵，即奎尔多雷，是{link:great-sundering}大分裂{/link}之后渡海而来的上层精灵流亡者的后代。他们在{link:lordaeron}洛丹伦{/link}北部的森林中建立了{link:quel-thalas}奎尔萨拉斯{/link}王国及其辉煌的首都银月城。数千年来，他们是{link:eastern-kingdoms}东部王国{/link}{link:arcane-magic}奥术魔法{/link}的大师。在{link:third-war}第三次战争{/link}中，他们的王国几乎被摧毁。]=],
		},
		{
			title = "起源",
			text = [=[{link:great-sundering}大分裂{/link}之后，{link:night-elves}暗夜精灵{/link}禁止使用{link:arcane-magic}奥术魔法{/link}。由{red:dath-remar-sunstrider}达斯雷玛·逐日者{/red}率领的不肯服从的上层精灵遭到了流放。他们向东航行，经过长久的漂泊来到北方的森林，在那里与阿曼尼{link:trolls}巨魔{/link}争夺新的家园。他们在那里创造了太阳之井，一个维系他们族人的奥术力量之泉。当阿曼尼起兵反抗他们时，他们与{link:arathor}阿拉索{/link}的{link:humans}人类{/link}结盟，传授他们魔法，并一起赢得了{link:troll-wars}巨魔战争{/link}。]=],
		},
		{
			title = "天性与习俗",
			text = [=[高等精灵优雅、骄傲而博学。他们热爱美与魔法，许多人看不起年轻的种族。他们的游侠是北方最出色的弓箭手。他们与太阳之井的联系如此之深，以至于开始依赖它的力量。]=],
		},
		{
			title = "当今",
			text = [=[在{link:third-war}第三次战争{/link}中，{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}率领{link:scourge}天灾军团{/link}进入{link:quel-thalas}奎尔萨拉斯{/link}。他杀死了国王安纳斯特里亚·逐日者，并利用太阳之井复活了巫妖{link:kel-thuzad}克尔苏加德{/link}。游侠将军{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}在保卫家园时阵亡。少数幸存者仍然四散各处：有些人仍守着奎尔萨拉斯残存的土地，有些人为{link:alliance}联盟{/link}和{link:kirin-tor}肯瑞托{/link}效力，还有一小队人守着{link:the-hinterlands}辛特兰{/link}的{link:quel-danil-lodge}奎尔丹尼小屋{/link}。逐日者王朝的继承人凯尔萨斯王子召集了许多幸存者，并为了纪念死者，将他们改名为辛多{link:farmer-ray}雷{/link}，即血精灵。此后他的境况如何，这片土地上没有任何编年史能够说清。]=],
		},
	},
})

Translate("zhCN", "kobolds", {
	title = "狗头人",
	aliases = { "狗头人" },
	sections = {
		{
			title = "概述",
			text = [=[狗头人是一种身材矮小、形似老鼠的生物，居住在{link:azeroth}艾泽拉斯{/link}各地的矿洞和洞穴中。他们胆小、贪婪，也不怎么聪明，但数量极多。只要哪座旧矿无人看守，狗头人就会搬进去。每个狗头人头上都顶着一支蜡烛来照亮隧道，每个狗头人都宁死也不肯放弃它。]=],
		},
		{
			title = "起源",
			text = [=[没有任何编年史记载狗头人最初从何而来。{link:explorers-league}探险者协会{/link}的一些发掘者相信，他们起源于地底深处的{link:troggs}石腭怪{/link}。无论起源如何，他们早在{link:tirisfal-glades}提瑞斯法{/link}最初的定居者那里就已是一大麻烦，从那以后便一直困扰着矿工。]=],
		},
		{
			title = "天性与习俗",
			text = [=[狗头人喜爱黑暗的隧道，却害怕真正的黑暗，他们的蜡烛是他们拥有的最珍贵的东西。偷走一支蜡烛是最严重的罪行，小偷会因此遭到一番斥责。他们没完没了地挖掘，囤积一切闪闪发光的东西。他们的地卜师施展粗陋的火焰与岩石魔法。大多数狗头人只在走投无路时才肯战斗，但成群结队时，他们足以压倒一名粗心的矿工。]=],
		},
		{
			title = "当今",
			text = [=[狗头人盘踞在{link:elwynn-forest}艾尔文森林{/link}和{link:westfall}西部荒野{/link}的矿洞中，挖掘着留不住的{link:ginro-hearthkindle}金{/link}子。据说驱使他们的是{link:riverpaw-gnolls}河爪豺狼人{/link}，而后者又与{link:defias-brotherhood}迪菲亚潜行者{/link}有往来。隧道鼠狗头人困扰着{link:loch-modan}洛克莫丹{/link}的{link:dwarves}矮人{/link}，而在{link:kalimdor}卡利姆多{/link}，狗头人在{link:stonetalon-mountains}石爪山脉{/link}为{link:venture-company}风险投资公司{/link}挖矿。]=],
		},
	},
})

Translate("zhCN", "gnolls", {
	title = "豺狼人",
	aliases = { "豺狼人" },
	sections = {
		{
			title = "概述",
			text = [=[豺狼人是形似鬣狗的生物，漫游在{link:eastern-kingdoms}东部王国{/link}和{link:kalimdor}卡利姆多{/link}的荒野中。他们野蛮、好斗、贪食，看重力量胜过一切。他们以群和氏族为单位生活，每一群都由其中最强者统治，他们劫掠其他民族的农场和道路，抢夺食物和财物。]=],
		},
		{
			title = "起源",
			text = [=[豺狼人是{link:azeroth}艾泽拉斯{/link}一个古老的种族，没有任何编年史记载他们的起源。他们是北方最早的{link:humans}人类{/link}定居者所面对的危险之一。{link:kingdom-of-stormwind}暴风王国{/link}记得一段更黑暗的时期，当时{link:redridge-gnolls}赤脊山豺狼人{/link}的一位族群领主加尔范将各氏族集结成一支大军，袭击王国的农场。国王巴拉森·乌瑞恩骑马出征，杀死了他，随后各个族群在争斗中自相残杀。]=],
		},
		{
			title = "天性与习俗",
			text = [=[豺狼人更喜欢让别人替他们干活。他们的首领驱使弱者走在前面，他们乐于为任何许诺给他们食物和战利品的更强的主人效力。他们的秘法师施行一种粗陋的萨满之术。他们狡猾到懂得设置陷阱和伏击，也残忍到以此为乐。]=],
		},
		{
			title = "当今",
			text = [=[豺狼人几乎侵扰着{link:humans}人类{/link}土地的每一处边境。{link:riverpaw-gnolls}河爪豺狼人{/link}劫掠{link:elwynn-forest}艾尔文森林{/link}和{link:westfall}西部荒野{/link}。{link:redridge-gnolls}赤脊山豺狼人{/link}和{link:shadowhide-gnolls}暗皮豺狼人{/link}在{link:redridge-mountains}赤脊山{/link}游荡，后者受术士{link:morganth}大魔导师杜内{/link}奴役。藓皮豺狼人出没于{link:wetlands}湿地{/link}，烂皮豺狼人为{link:scourge}天灾军团{/link}挖掘{link:tirisfal-glades}提瑞斯法林地{/link}的死者，其他氏族则在{link:hillsbrad-foothills}希尔斯布莱德{/link}的丘陵和{link:feralas}菲拉斯{/link}的森林中游荡。]=],
		},
	},
})

Translate("zhCN", "riverpaw-gnolls", {
	title = "河爪豺狼人",
	aliases = { "河爪豺狼人", "河爪" },
	sections = {
		{
			title = "概述",
			text = [=[河爪是困扰{link:kingdom-of-stormwind}暴风王国{/link}南部土地的{link:gnolls}豺狼人{/link}氏族。他们的活动范围沿着{link:elwynn-forest}艾尔文森林{/link}的边境，穿过{link:westfall}西部荒野{/link}的田野，一直延伸到{link:redridge-mountains}赤脊山{/link}。他们劫掠农场，伏击旅人，与王国所能抽调的少数士兵作战。他们之中最令人畏惧的是巨大的豺狼人{link:hogger}霍格{/link}。]=],
		},
		{
			title = "事迹",
			text = [=[自从王国的军队被派往海外，河爪变得越发大胆。他们从林边空地出来袭击{link:elwynn-forest}艾尔文森林{/link}南部的农场，{link:westbrook-garrison}西泉要塞{/link}为志愿者带回的每一只爪子支付赏{link:ginro-hearthkindle}金{/link}。在{link:westfall}西部荒野{/link}，他们的营地更加庞大。人民军发现了一些迹象，表明河爪并非只为自己而战：他们在矿洞中驱使{link:kobolds}狗头人{/link}奴隶，并与{link:defias-brotherhood}迪菲亚潜行者{/link}有往来。{link:stormwind-city}暴风城{/link}中许多人都在猜测，是谁在武装他们，又是谁赋予了他们不同寻常的狡诈。]=],
		},
	},
})

Translate("zhCN", "murlocs", {
	title = "鱼人",
	aliases = { "鱼人" },
	sections = {
		{
			title = "概述",
			text = [=[鱼人是一种体型矮小、形似鱼类的生物，生活在{link:azeroth}艾泽拉斯{/link}的海岸、湖泊和河流沿岸。他们用两条腿走路，说着一种其他民族都听不懂的咕噜咕噜的语言，并会突然成群地发起攻击。{link:eastern-kingdoms}东部王国{/link}和{link:kalimdor}卡利姆多{/link}的每一个渔夫都有一个关于鱼人的故事。]=],
		},
		{ title = "起源", text = "没有任何编年史记载鱼人从何而来。自有民族记录历史以来，他们就一直出没于世界的海岸，而且他们似乎对陆地居民的战争毫不在意。" },
		{
			title = "天性与习俗",
			text = [=[鱼人以{link:horde}部落{/link}为单位生活，住在沿水边搭建的棚屋村落里。他们捕鱼，也捕食任何靠近他们海岸的东西。他们的神谕者和潮汐猎手施展一种简单的水与风暴的魔法。单个鱼人很少构成危险，但他们很少单独出现。一个鱼人遭到攻击时，其他鱼人就会伴着一声可怕的叫喊从浅水中冒出来。]=],
		},
		{
			title = "当今",
			text = [=[随着诸王国日渐衰弱，鱼人变得越发大胆。他们劫掠{link:elwynn-forest}艾尔文森林{/link}的湖岸和{link:westfall}西部荒野{/link}的海岸。蓝腮部族出没于{link:wetlands}湿地{/link}的{link:swamp-of-sorrows}沼泽{/link}，灰雾部族出没于{link:darkshore}黑海岸{/link}的海岸。在每一处海岸，从{link:stranglethorn-vale}荆棘谷{/link}到{link:durotar}杜隆塔尔{/link}，他们的棚屋都立在水边。]=],
		},
	},
})

Translate("zhCN", "quilboar", {
	title = "野猪人",
	aliases = { "野猪人" },
	sections = {
		{
			title = "概述",
			text = [=[野猪人是一个野蛮的猪人种族，居住在{link:the-barrens}贫瘠之地{/link}南部及其周边地区。他们身上长满鬃毛和尖刺，在巨大而纠结的荆棘藤蔓之间安家。他们几乎敌视所有其他种族，长久以来一直与{link:tauren}牛头人{/link}和{link:orcs}兽人{/link}交战。]=],
		},
		{
			title = "起源",
			text = [=[野猪人认为自己是伟大的野猪半神阿迦玛甘的子孙。在{link:war-of-the-ancients}上古战争{/link}中，阿迦玛甘与{link:burning-legion}燃烧军团{/link}作战并被杀死。在他的血洒落之处，巨大的荆棘藤蔓从地里长了出来。这些荆棘成了剃刀荆棘，野猪人把它们当作神圣的家园。]=],
		},
		{
			title = "天性与习俗",
			text = [=[野猪人凶猛且领地意识强烈。他们的{link:horde}部落{/link}由督军领导，他们的地卜师向大地祈求力量。他们崇敬阿迦玛甘的记忆，视剃刀荆棘为圣地。他们的一些女祭司转向了更黑暗的技艺，一些战士则转投了更黑暗的主人。]=],
		},
		{
			title = "当今",
			text = [=[{link:bristleback-quilboar}钢鬃{/link}{link:horde}部落{/link}劫掠着{link:durotar}杜隆塔尔{/link}的边缘和{link:the-barrens}贫瘠之地{/link}北部，刺背部落则侵扰着{link:mulgore}莫高雷{/link}的{link:burning-steppes}平原{/link}。在南方，野猪人居住在{link:razorfen-kraul}剃刀沼泽{/link}和{link:razorfen-downs}剃刀高地{/link}巨大的荆棘洞穴中。据说在剃刀高地，一个名为“{link:death-s-head}亡首{/link}”的教派已投靠{link:scourge}天灾军团{/link}，如今有一个巫妖住在他们中间。]=],
		},
	},
})

Translate("zhCN", "centaurs", {
	title = "半人马",
	aliases = { "半人马" },
	sections = {
		{
			title = "概述",
			text = [=[半人马是{link:kalimdor}卡利姆多{/link}一个残忍而好战的种族。他们有着人的上身和马的身体，是可怕的劫掠者，成群结队地迅速而无情地驰骋。世世代代，他们一直是{link:tauren}牛头人{/link}最大的敌人。]=],
		},
		{
			title = "起源",
			text = [=[据说半人马是半神{link:cenarius}塞纳留斯{/link}之子扎尔塔与大地{link:elements}元素{/link}公主瑟莱德丝结合的后裔。他们最早的子嗣残忍至极，在一阵嫉妒中杀死了自己的父亲。瑟莱德丝将扎尔塔安葬在{red:maraudon}玛拉顿{/red}的洞窟中，据说他的灵魂至今仍徘徊在那里。]=],
		},
		{
			title = "天性与习俗",
			text = [=[半人马以游牧和劫掠为生。他们认为强者应当从弱者那里夺取他们想要的东西。他们的可汗领导着各部族，而在没有其他敌人时，各部族就互相厮杀。他们是熟练的骑手和弓箭手，很少手下留情。]=],
		},
		{
			title = "当今",
			text = [=[{link:kolkar-centaurs}科卡尔部族{/link}在{link:the-barrens}贫瘠之地{/link}游荡，其劫掠者袭击那里的{link:orcs}兽人{/link}前哨。加拉克部族驰骋在{link:thousand-needles}千针石林{/link}。在{link:desolace}凄凉之地{/link}，玛格拉姆和{link:gill}吉尔{/link}吉斯进行着长久的争斗，双方都声称得到了瑟莱德丝的眷顾。玛洛迪守卫着玛拉顿本身的入口。尽管{link:cairne-bloodhoof}凯恩{/link}将半人马逐出了{link:mulgore}莫高雷{/link}，他们并没有忘记{link:tauren}牛头人{/link}。]=],
		},
	},
})

Translate("zhCN", "furbolgs", {
	title = "熊怪",
	aliases = { "熊怪" },
	sections = {
		{
			title = "概述",
			text = [=[熊怪是{link:kalimdor}卡利姆多{/link}北方森林中形似熊的种族。他们长久以来是一个温和而和平的民族，是{link:night-elves}暗夜精灵{/link}和德鲁伊的朋友。近年来，一种精神上的疾病降临到他们大多数部族身上，许多熊怪变得野蛮而充满敌意。]=],
		},
		{
			title = "起源",
			text = [=[熊怪自远古时代起就生活在{link:kalimdor}卡利姆多{/link}的森林中。他们曾被视为{link:night-elves}卡多雷{/link}的盟友之一。没有任何编年史更详细地记载他们的起源。]=],
		},
		{
			title = "天性与习俗",
			text = [=[熊怪以部族为单位生活，住在深藏于林中的巢穴和村落里。他们的萨满祭司通晓森林之道。大多数熊怪满足于安静地生活，与邻居和平交易。]=],
		},
		{
			title = "当今",
			text = [=[自{link:third-war}第三次战争{/link}以来残留在森林中的恶魔污染已让许多部族陷入疯狂。{link:ashenvale}灰谷{/link}的{link:thistlefur-village}蓟皮{/link}和污林，{link:felwood}费伍德森林{/link}的{link:deadwood-furbolgs}死木{/link}，{link:darkshore}黑海岸{/link}的{link:blackwood-furbolgs}黑木{/link}，{link:teldrassil}泰达希尔{/link}的{link:gnarlpine-furbolgs}脊骨{/link}，以及{link:winterspring}冬泉谷{/link}的{link:winterfall-furbolgs}寒水{/link}，都已背叛了他们的老朋友。只有{link:timbermaw-furbolgs}木喉部族{/link}抵挡住了腐化。他们守卫着{link:timbermaw-hold}木喉要塞{/link}的通道，在外人证明自己之前绝不信任他们。]=],
		},
	},
})

Translate("zhCN", "harpies", {
	title = "鹰身人",
	aliases = { "鹰身人" },
	sections = {
		{
			title = "概述",
			text = [=[鹰身人是{link:kalimdor}卡利姆多{/link}的有翼生物，有着女人的身体和鸟的翅膀与利爪。她们残忍、狡猾而恶毒，从高处的巢穴中扑向旅人。]=],
		},
		{ title = "起源", text = "在本记录所知的任何编年史中，都没有关于鹰身人起源的记载。" },
		{
			title = "天性与习俗",
			text = [=[鹰身人以族群为单位生活，由女族长统治。她们在悬崖和山脊上筑巢，俯冲下来攻击任何比自己弱小的东西。她们喜爱偷来的闪亮之物，也喜爱捕获之人的血肉。她们的女巫掌握着黑暗魔法。]=],
		},
		{
			title = "当今",
			text = [=[{link:windfury-harpies}狂风鹰身人{/link}在{link:mulgore}莫高雷{/link}的山脊上筑巢，令{link:tauren}牛头人{/link}十分恼火。巫翼鹰身人栖息在{link:the-barrens}贫瘠之地{/link}，血怒鹰身人在{link:stonetalon-mountains}石爪山脉{/link}，北泉鹰身人在{link:feralas}菲拉斯{/link}。在她们的巢穴之下，{link:kalimdor}卡利姆多{/link}的道路并不安全。]=],
		},
	},
})

Translate("zhCN", "troggs", {
	title = "石腭怪",
	aliases = { "石腭怪" },
	sections = {
		{
			title = "概述",
			text = [=[石腭怪是生活在地底深处的野蛮生物，皮肤如石。他们强壮、愚蠢，而且永远充满攻击性。漫长岁月里，他们一直藏在深处。如今他们来到了地表，并带来了毁灭。]=],
		},
		{
			title = "起源",
			text = [=[{link:uldaman}奥达曼{/link}的记录记载，石腭怪和土灵一样是泰坦所造。他们是一种有缺陷的造物，泰坦将他们封存在世界深处的宝库中。{link:explorers-league}探险者协会{/link}相信，{link:dwarves}矮人{/link}在奥达曼挖掘时惊动了那些宝库，从那以后石腭怪便一直在扩散。]=],
		},
		{ title = "天性与习俗", text = "石腭怪以部族为单位生活，由其中最强者领导。他们的萨满祭司施展粗陋的大地魔法。除了战斗和吃，他们对什么都不太在意。" },
		{
			title = "当今",
			text = [=[石腭怪在{link:gnomeregan}诺莫瑞根{/link}地下崛起，把{link:gnomes}侏儒{/link}赶出了他们的城市。他们在{link:dun-morogh}丹莫罗{/link}和{link:loch-modan}洛克莫丹{/link}与{link:dwarves}矮人{/link}作战，成群地涌过{link:uldaman}奥达曼{/link}和{link:badlands}废土{/link}。矮人在任何地方往深处挖掘时，都害怕会发现更多的石腭怪。]=],
		},
	},
})

Translate("zhCN", "ogres", {
	title = "食人魔",
	aliases = { "食人魔" },
	sections = {
		{
			title = "概述",
			text = [=[食人魔是力大无穷、头脑迟钝的巨大野兽。有些长着两个脑袋，少数是狡猾的术士。他们中的大多数随{link:orcs}兽人{/link}从德拉诺来到{link:azeroth}艾泽拉斯{/link}，如今许多氏族居住在两片大陆的荒野中。]=],
		},
		{
			title = "起源",
			text = [=[在{link:second-war}第二次战争{/link}中，食人魔为{link:orcs}兽人{/link}{link:horde}部落{/link}效力。术士{link:gul-dan}古尔丹{/link}赐予其中一些施法的天赋，这些食人魔法师在{link:eastern-kingdoms}东部王国{/link}令人闻风丧胆。他们之中最强大的古加尔领导着{link:twilight-s-hammer}暮光之锤{/link}氏族。部落战败后，食人魔各氏族散入了丘陵和山脉。]=],
		},
		{ title = "天性与习俗", text = "食人魔好战而贪婪。他们只尊重力量，并为争夺领导权而内斗。他们的酋长用棍棒统治，他们的法师用恐惧统治。" },
		{
			title = "当今",
			text = [=[食人魔各氏族占据着{link:redridge-mountains}赤脊山{/link}、{link:stranglethorn-vale}荆棘谷{/link}、{link:alterac-mountains}奥特兰克山脉{/link}和{link:arathi-highlands}阿拉希高地{/link}的丘陵。在{link:kalimdor}卡利姆多{/link}，戈杜尼食人魔出没于{link:feralas}菲拉斯{/link}，戈多克食人魔统治着{red:dire-maul}厄运之槌{/red}的废墟。在{link:dustwallow-marsh}尘泥沼泽{/link}，石槌氏族已失去了昔日的力量，其中一些食人魔如今与{link:orcs}兽人{/link}生活在一起。]=],
		},
	},
})

Translate("zhCN", "naga", {
	title = "纳迦",
	aliases = { "纳迦" },
	sections = {
		{
			title = "概述",
			text = [=[纳迦是深海中的蛇形生物。他们曾是上层精灵阶层的{link:night-elves}暗夜精灵{/link}。如今他们长着带鳞的尾巴和残忍的面孔，从深海归来侵扰世界的海岸。]=],
		},
		{
			title = "起源",
			text = [=[当{link:well-of-eternity}永恒之井{/link}在{link:great-sundering}大分裂{/link}中被摧毁时，{link:queen-azshara}艾萨拉女王{/link}的宫殿连同她的整个宫廷一起被大海吞没。深海中的某种东西拯救了他们，也改变了他们。溺水的上层精灵变成了纳迦。一万年来，他们隐居在海浪之下。在{link:third-war}第三次战争{/link}时期，他们再次崛起，并曾一度为{link:illidan-stormrage}伊利丹·怒风{/link}效力。]=],
		},
		{
			title = "天性与习俗",
			text = [=[纳迦骄傲、怨恨而充满野心。他们的海妖是强大的女术士，能够号令海水与风暴。他们的侍从是可怕的战士。据说他们在深海中仍尊奉{link:azshara}艾萨拉{/link}。]=],
		},
		{
			title = "当今",
			text = [=[纳迦已占据了{link:azshara}艾萨拉{/link}、{link:darkshore}黑海岸{/link}、{link:ashenvale}灰谷{/link}和{link:desolace}凄凉之地{/link}的部分海岸。他们出没于{link:blackfathom-deeps}黑暗深渊{/link}那座被淹没的神庙。他们在{link:kalimdor}卡利姆多{/link}的海岸上寻找什么，{link:night-elves}暗夜精灵{/link}并不知道。]=],
		},
	},
})

Translate("zhCN", "satyrs", {
	title = "萨特",
	aliases = { "萨特" },
	sections = {
		{
			title = "概述",
			text = [=[萨特是森林中的恶魔，头生双角，长着山羊的腿。他们曾是出卖自己给{link:burning-legion}燃烧军团{/link}的上层精灵。如今他们出没于{link:kalimdor}卡利姆多{/link}北部被腐化的森林中，所到之处散播着{link:fel-magic}邪能魔法{/link}的污染。]=],
		},
		{
			title = "起源",
			text = [=[在{link:war-of-the-ancients}上古战争{/link}中，{link:queen-azshara}艾萨拉女王{/link}的顾问{link:shadow-priest-sarvis}萨维斯{/link}大人是第一个侍奉恶魔的上层精灵。他战败后，{link:burning-legion}燃烧军团{/link}的主宰将他重塑为第一个萨特。萨维斯又让许多上层精灵遭受了同样的命运。萨特在整场战争中为燃烧军团而战，许多萨特在{link:great-sundering}大分裂{/link}中幸存了下来。]=],
		},
		{
			title = "天性与习俗",
			text = [=[萨特残忍、狡诈，渴求力量。无论{link:burning-legion}燃烧军团{/link}是近是远，他们都侍奉恶魔。他们的魔法是邪能，他们腐化自己栖居的土地。他们的部族住在被他们糟蹋的森林中的黑暗{link:moonglade}林地{/link}里。]=],
		},
		{
			title = "当今",
			text = [=[自{link:third-war}第三次战争{/link}以来，萨特已蔓延到各处森林。他们盘踞在{link:felwood}费伍德森林{/link}和{link:ashenvale}灰谷{/link}，{link:satyrnaar}萨提纳尔{/link}是他们在灰谷的据点，他们还潜伏在{link:azshara}艾萨拉{/link}的废墟和{red:dire-maul}厄运之槌{/red}的深处。{link:sentinels}哨兵{/link}们毫不留情地猎杀他们。]=],
		},
	},
})
